#!/usr/bin/env node
/**
 * bundle-pdfjs.mjs — inlines pdfjs-dist (core + worker) and the engine
 * bootstrap into a single offline HTML string module.
 *
 * Output: src/engine/html/engineHtml.ts  (GENERATED, gitignored)
 * No CDN, no network at runtime (PRD §7.3). Run: `npm run bundle:pdfjs`.
 * CI runs this after `npm ci`, before prebuild.
 *
 * Bundle shape: ONE <script type="module"> containing, in order:
 *   1. pdf.js core (trailing `export {...}` rewritten to `const pdfjsLib = {...}`)
 *   2. workerSrc → Blob URL (worker is an ES module; pdf.js creates it with
 *      `new Worker(url, {type:"module"})`; same-origin wrapper path is offline-safe)
 *   3. lines.js (shared text-line clustering)
 *   4. bootstrap.js (the RN↔WebView protocol)
 * A single module scope avoids classic/module ordering hazards and keeps
 * `pdfjsLib` visible to the engine code without globals.
 */
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const outFile = path.join(root, 'src', 'engine', 'html', 'engineHtml.ts');

function resolvePdfjs(sub) {
  try {
    return require.resolve(`pdfjs-dist/${sub}`);
  } catch {
    return null;
  }
}

// Legacy build preferred (broadest WebView compat); fall back to standard.
const corePath =
  resolvePdfjs('legacy/build/pdf.mjs') ?? resolvePdfjs('build/pdf.mjs');
const workerPath =
  resolvePdfjs('legacy/build/pdf.worker.mjs') ??
  resolvePdfjs('build/pdf.worker.mjs');

if (!corePath || !workerPath) {
  console.error('bundle-pdfjs: could not resolve pdfjs-dist build files.');
  process.exit(1);
}

const linesPath = path.join(root, 'src', 'engine', 'html', 'lines.js');
const bootstrapPath = path.join(root, 'src', 'engine', 'html', 'bootstrap.js');

/** Make a JS source safe to inline inside <script> in HTML. */
function inlineSafe(src) {
  return src.replace(/<\/script/gi, '<\\/script').replace(/<!--/g, '<\\!--');
}

/**
 * Rewrite the core's trailing `export { A, B as C, ... };` into
 * `const pdfjsLib = { A, C: B, ... };` so the engine code in the same
 * module scope can use it without a separate import.
 */
function exposeCore(src) {
  // Drop the sourceMappingURL trailer (the .map isn't inlined).
  const noMap = src.replace(/\/\/# sourceMappingURL=.*$/m, '').trimEnd();
  const m = noMap.match(/export\s*\{([^}]*)\}\s*;?\s*$/);
  if (!m) throw new Error('bundle-pdfjs: core export statement not found');
  const entries = m[1]
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => {
      const am = s.match(/^(\S+)\s+as\s+(\S+)$/);
      return am ? `${am[2]}: ${am[1]}` : `${s}: ${s}`;
    });
  return noMap.slice(0, m.index).trimEnd() + `\nconst pdfjsLib = {\n${entries.join(',\n')}\n};\n`;
}

const core = inlineSafe(exposeCore(fs.readFileSync(corePath, 'utf8')));
const worker = inlineSafe(fs.readFileSync(workerPath, 'utf8'));
const lines = inlineSafe(fs.readFileSync(linesPath, 'utf8'));
const bootstrap = inlineSafe(fs.readFileSync(bootstrapPath, 'utf8'));

const moduleJs =
  core +
  '\n;var __PDFJS_WORKER_SRC__=' + JSON.stringify(worker) + ';' +
  '\npdfjsLib.GlobalWorkerOptions.workerSrc=' +
  'URL.createObjectURL(new Blob([__PDFJS_WORKER_SRC__],{type:"text/javascript"}));\n' +
  lines +
  '\n' +
  bootstrap +
  '\n';

const html =
  '<!DOCTYPE html><html><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
  '<body><script type="module">' +
  moduleJs +
  '</script></body></html>';

const ts =
  '// GENERATED by scripts/bundle-pdfjs.mjs — do not edit. Run `npm run bundle:pdfjs`.\n' +
  `export const ENGINE_HTML: string = ${JSON.stringify(html)};\n`;

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, ts);
console.log(`bundle-pdfjs: wrote ${outFile}`);
console.log(`  core:   ${(fs.statSync(corePath).size / 1024).toFixed(0)} KiB  (${path.basename(corePath)})`);
console.log(`  worker: ${(fs.statSync(workerPath).size / 1024).toFixed(0)} KiB  (${path.basename(workerPath)})`);
console.log(`  html:   ${(Buffer.byteLength(html, 'utf8') / 1024).toFixed(0)} KiB total`);
